  var SIM_SPEED = 70;       // 模拟游览的速度，画布像素/秒
  var GEO_OPTIONS = { enableHighAccuracy: true, maximumAge: 5000, timeout: 20000 };
  var QA_PAGE = 20;         // 游客互动每次取几条
  var QA_MAX = 100;         // 一个问题最多几个字，与服务端一致
  var QA_TIMEOUT_MS = 70000;

